const outer = $json || {};
const payload = outer.body && typeof outer.body === 'object' ? outer.body : outer;
const data = payload.data && typeof payload.data === 'object' ? payload.data : payload;
const rawEvent = String(payload.event || payload.type || '').toUpperCase().replace(/[.\- ]/g, '_');
const event = rawEvent.includes('CONNECTION_UPDATE') ? 'CONNECTION_UPDATE'
  : rawEvent.includes('MESSAGES_UPSERT') ? 'MESSAGES_UPSERT' : rawEvent;
const key = data.key || data.message?.key || {};
const remoteJid = String(key.remoteJid || data.sender || data.from || '');
const senderPhone = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
const message = data.message || {};
const messageText = String(
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  message.videoMessage?.caption ||
  message.documentMessage?.caption ||
  message.buttonsResponseMessage?.selectedButtonId ||
  message.listResponseMessage?.singleSelectReply?.selectedRowId ||
  data.text || ''
).trim();
const match = messageText.match(/^\s*SIM\s+([A-F0-9]{8})\s*$/i);
const simpleConfirmation = /^SIM$/i.test(messageText);
const headers = outer.headers || {};
const token = headers['x-arenapro-webhook'] || headers['X-ArenaPro-Webhook'] || '';
const instanceName = String(payload.instance || payload.instanceName || data.instance || '');
const state = String(data.state || data.instance?.state || payload.state || payload.status || '').toUpperCase();
const isConnection = event === 'CONNECTION_UPDATE';
const isMessage = event === 'MESSAGES_UPSERT';
const ignored = (!isConnection && !isMessage)
  || (isMessage && (key.fromMe === true || remoteJid.includes('@g.us') || remoteJid.includes('status@') || !senderPhone || !messageText));
return { json: {
  ignore: Boolean(ignored),
  event,
  instanceName,
  senderPhone,
  messageId: String(key.id || data.id || ''),
  messageText,
  confirmationCode: match ? match[1].toUpperCase() : '',
  simpleConfirmation,
  connectionStatus: state,
  phoneNumber: String(data.ownerJid || data.number || payload.number || '').replace(/@s\.whatsapp\.net$/, ''),
  webhookToken: String(token)
} };

const booking = $json?.booking;
if (booking?.confirmed) {
  const when = new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(booking.start_at));
  const amount = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(booking.amount) || 0);
  return { json: { text: 'Reserva confirmada! ' + when + ' · valor ' + amount + '. O pagamento fica pendente para acerto com a arena.' } };
}
if (booking?.reason === 'multiple_pending_offers') {
  return { json: { text: 'Encontrei mais de uma oferta pendente. Para evitar confirmar o horário errado, responda SIM seguido do código da oferta que deseja confirmar.' } };
}
if (booking?.reason === 'no_pending_offer') {
  return { json: { text: 'Não encontrei uma oferta pendente dentro do prazo de 15 minutos. Consulte os horários novamente para criar uma nova oferta.' } };
}
return { json: { text: 'Não consegui confirmar essa oferta. Ela pode ter expirado ou o horário pode ter sido ocupado. Consulte os horários novamente.' } };
